      'THE NIGHT KNEW MY NAME',
      'They called it space—',
      'I called it impossible.',
      'They called them stars—',
      'I called them by name.',
      'Look up, little light, look far, look free,',
      'Every star has a story crossing centuries.',
      'Algenib, Betelgeuse, Sirius, Polaris—',
