      'A Cepheid softly breathing in celestial harmony.',
      'Sailors found salvation in its steady-seeming role,',
      'A silver signal sitting near the northern pole.',
      'But Earth spins and sways like a slow, dreaming top,',
      'So even North is borrowed; even guide stars swap.',
      'Thuban held the title; Vega waits beyond,',
      'The sky keeps rearranging what we thought would carry on.',
      'Still Polaris keeps pointing while our brief years pass,',
      'A pin through the heavens, a compass through the black.',
