  {
    id: 'the-least-pay-the-most',
    title: 'The Least Pay the Most',
    artist: 'bZ',
    file: '/audio/the-least-pay-the-most.mp3',
    cover: '/art/cover-flawless-execution.jpg',
    album: 'flawless-execution',
    vibe: 'Economic justice drill — the broke pay more while the wealthy build gold-trimmed churches, the math of oppression laid bare',
    zone: { row: 22, col: 2 },
    lyrics: [
      '# **The Least Pay the Most**',
      '**[Intro]**',
      'They built a brutal business where the broke pay more,',
      'Then boast about the Bible from a gold-trimmed floor.',
      'They praise a peaceful Prophet, then profit from the poor—',
      'Preaching grace on Sunday, Monday guarding greed’s front door.',
      '**[Verse 1]**',
      'Balance barely breathing, bank account in red,',
      'Bankers bite another fee from money already dead.',
      'Five dollars in the negative, thirty-five gets drained,',
      'Poverty gets punished while the profit gets proclaimed.',
      'Bills bounce badly, penalties pile,',
      'Fees breed fees in a fatal file.',
      'Paycheck posts late, but the landlord won’t wait,',
      'So the poor pay a premium for arriving past the date.',
      'Credit costs the most when you need it to cope,',
      'Payday lenders package desperation up as hope.',
      'The wealthy win low rates and lock their wealth in stores;',
      'Workers borrow just to keep some supper in the drawers.',
      '**[Pre-Chorus]**',
      'Every office offers obstacles and demands,',
      'Every lifeline leaves a ledger in your hands.',
      'They swear the system’s equal since the statutes stay the same,',
      'But a spark costs more when you’re already in the flame.',
      '**[Chorus]**',
      'The least pay the most, coast to coast,',
      'For a room, a ride, the right to stay afloat.',
      'Banks take bites and the DMV takes days,',
      'Every system sells survival in a hundred hidden ways.',
      'They quote Christ clearly, then contradict His call,',
      'Sing about the Savior while the starving scrape the wall.',
      'One penny from the poor holds more than fortunes from the rich,',
      'Still churches cheer the wealthy while the poor stay in the ditch.',
      '**[Verse 2]**',
      'Need a car for the career, need the career for the car,',
      'Need a license from an office painfully far.',
      'Miss a morning making money, spend the afternoon in line,',
      'Government grabs your wages while it wastes away your time.',
      'Booked back in April, still you wait into the night,',
      'Bring a birth certificate—they claim it isn’t right.',
      'One box blank, back you go, brokenhearted through the door,',
      'The DMV keeps demonstrating: poor folks pay more.',
      'No paid leave, so you labor while your lungs burn sick,',
      'Lose one shift and eviction starts to count down quick.',
      'Can’t afford the clinic, so the sickness settles deep,',
      'Then the ambulance adds anguish with a bill you cannot beat.',
      'Cheap shoes crack quickly, so you purchase pair on pair,',
      'Cheap meals ease the hunger while they slowly strip your health.',
      'The rich buy quality once; the poor replace and replace,',
      'Then society scolds the struggling with a shameless face.',
      '**[Chorus]**',
      'The least pay the most, coast to coast,',
      'For a meal, medicine, a modest bit of hope.',
      'Courts collect cash and the DMV takes days,',
      'Every system sells survival in a hundred hidden ways.',
      'They quote Christ clearly, then contradict His call,',
      'Build enormous temples while their neighbors beg and crawl.',
      'One penny from the poor holds sacrifice within;',
      'One dollar from abundance doesn’t wash away your sin.',
      '**[Bridge]**',
      'You memorize the message, mark the margins, quote the page,',
      'Then ignore the aching people crushed beneath the weight.',
      'You raise your hands to heaven, sing salvation sweet and loud,',
      'Then pass a freezing person like a shadow in the crowd.',
      'You know each sacred sentence, every sermon, every song,',
      'But faith without fair action is a fraud that funds the wrong.',
      'You say the meek are mighty, say the last will lead the first,',
      'Then maintain the very machines that make their misery worse.',
      'Banks benefit from brokenness, courts capitalize on fate,',
      'Landlords leverage hunger, leaders manufacture hate.',
      'The danger isn’t distant; it is printed on the fee,',
      'Glowing green above the counter at the local DMV.',
      '**[Breakdown]**',
      'Thirty-five because you lacked five—',
      'They call that keeping banking alive.',
      'Late rent fee because rent was late—',
      'They deepen the ditch, then debate your fate.',
      'But people pressed together can pressure every wall,',
      'A thousand steady voices can outshout one marble hall.',
      'Mercy made into policy, dignity made law—',
      'We can build a better system than the broken one we saw.',
      '**[Final Chorus]**',
      'The least pay the most—but we won’t anymore,',
      'We’ll bring the buried burden to the public’s front door.',
      'Banks took bites and the DMV took days,',
      'Now we’re naming every punishment and changing every way.',
      'Stop quoting Christ as camouflage for coldness and control,',
      'Start feeding every body, start protecting every soul.',
      'That penny from the poor is a precious piece of breath;',
      'Let compassion become practice, not a promise after death.',
      'The world may stand in peril, but the people still have power,',
      'Every hand can help a neighbor, every voice can move the hour.',
      'When mercy matters more than every margin, fee, and score,',
      'The people with the least won’t have to pay the most anymore.',
      '**[Outro]**',
      'Read the Scripture, live the meaning.',
      'Feed the hungry, fight the greed.',
      'Faith becomes a force for freedom',
      'When belief becomes a deed.'
    ],
    wisdom: '"They built a brutal business where the broke pay more" — the poverty tax is the steepest tax of all'
  }
